import sqlite3
conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
# Search for EX001 or BostonTech in all tables
tables = [r[0] for r in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]
for t in tables:
    cols = [r[1] for r in conn.execute(f'PRAGMA table_info({t})').fetchall()]
    for c in cols:
        try:
            rows = conn.execute(f'SELECT * FROM {t} WHERE CAST({c} AS TEXT) LIKE ?', ('%EX001%',)).fetchall()
            if rows:
                print(f'Found EX001 in {t}.{c}:')
                for r in rows: print(dict(r))
            rows = conn.execute(f'SELECT * FROM {t} WHERE CAST({c} AS TEXT) LIKE ?', ('%Boston%Tech%',)).fetchall()
            if rows:
                print(f'Found BostonTech in {t}.{c}:')
                for r in rows: print(dict(r))
            rows = conn.execute(f'SELECT * FROM {t} WHERE CAST({c} AS TEXT) LIKE ?', ('%boston%tech%',)).fetchall()
            if rows:
                print(f'Found bostontech in {t}.{c}:')
                for r in rows: print(dict(r))
        except:
            pass
conn.close()
"

